// mini_memo_core.h - 记忆类型
typedef enum {
    MEMO_TYPE_MEMO = 0,       // 普通备忘
    MEMO_TYPE_TODO = 1,        // 待办事项
    MEMO_TYPE_SCHEDULE = 2,    // 日程安排
} memo_type_t;

// 单条记忆
typedef struct {
    uint32_t id;               // 唯一标识
    memo_type_t type;          // 类型
    char content[200];         // 内容
    int64_t timestamp;         // 创建时间
    int64_t remind_at;         // 提醒时间（0=不提醒）
    bool is_read;              // 是否已读
} memo_item_t;
