123	static int pulse_encoder_init(void)
124	{
125	    s_encoder_device = rt_device_find("encoder1");
126	    if (s_encoder_device == RT_NULL)
127	    {
128	        LOG_E("Failed to find encoder device\n");
129	        return -RT_ERROR;
130	    }
131	    struct rt_encoder_configuration config;
132	    config.channel = GPT_CHANNEL_ALL;
133	
134	    rt_err_t result =
135	        rt_device_control((struct rt_device *)s_encoder_device,
136	                          PULSE_ENCODER_CMD_ENABLE, (void *)&config); // 使能
137	
138	    if (result != RT_EOK)
139	    {
140	        rt_kprintf("Failed to enable encoder\n");
141	        return -RT_ERROR;
142	    }
143	    return RT_EOK;
144	}
