200	static void battery_level_task(void *parameter)
201	{
202	    if (g_battery_mb == NULL)
203	    {
204	        rt_kprintf("Failed to create mailbox g_battery_mb\n");
205	        return;
206	    }
207	    uint8_t battery_percentage = 0;
208	    uint8_t shutdown_battery_percentage = 0; 
209	    // 初始化电池计算器
210	    battery_calculator_t battery_calc;
211	    battery_calculator_config_t calc_config = 
212	    {
213	        .charging_table = charging_curve_table,
214	        .charging_table_size = charging_curve_table_size,
215	        .discharging_table = discharge_curve_table,
216	        .discharging_table_size = discharge_curve_table_size,
217	        .charge_filter_threshold = 50,      // 充电滤波阈值
218	        .discharge_filter_threshold = 30,   // 放电滤波阈值
219	        .filter_count = 3,                   // 滤波计数阈值
220	        .secondary_filter_enabled = true,    // 启用二级滤波
221	        .secondary_filter_weight_pre = 90,   // 二级滤波前电压权重
222	        .secondary_filter_weight_cur = 10    // 二级滤波当前电压权重
223	    };
224	    
225	    battery_calculator_init(&battery_calc, &calc_config);
226	    rt_uint8_t current_status;
227	    while (1)
228	    {
229	        rt_device_t battery_device = rt_device_find("bat1");
230	        rt_adc_cmd_read_arg_t read_arg;
231	        read_arg.channel = 7; // 电池电量在通道7
232	        rt_err_t result =
233	            rt_adc_enable((rt_adc_device_t)battery_device, read_arg.channel);
234	        if (result != RT_EOK)
235	        {
236	            LOG_E("Failed to enable ADC for battery read\n");
237	            return;
238	        }
239	        rt_thread_mdelay(300);
240	        rt_uint32_t battery_level = rt_adc_read((rt_adc_device_t)battery_device, read_arg.channel);
241	        rt_kprintf("battery_level: %d\n", battery_level);
242	        rt_adc_disable((rt_adc_device_t)battery_device, read_arg.channel);
243	        if(g_low_power_mode)
244	        {
245	#ifdef BSP_USING_BOARD_SF32LB52_LCHSPI_ULP
246	            BSP_GPIO_Set(26, 1, 1);
247	            HAL_PIN_Set(PAD_PA26, GPIO_A26, PIN_PULLUP, 1);
248	            HAL_PIN_Set(PAD_PA10, I2C2_SCL, PIN_PULLUP, 1);
249	            HAL_PIN_Set(PAD_PA11, I2C2_SDA, PIN_PULLUP, 1);
250	            rt_thread_mdelay(10);
251	#endif
252	            battery_percentage = battery_calculator_get_percent(
253	                &battery_calc, 
254	                battery_level
255	            );
256	#ifdef BSP_USING_BOARD_SF32LB52_LCHSPI_ULP
257	            BSP_GPIO_Set(26, 0, 1);
258	            HAL_PIN_Set(PAD_PA26, GPIO_A26, PIN_NOPULL, 1);
259	            HAL_PIN_Set(PAD_PA10, GPIO_A10, PIN_PULLDOWN, 1);
260	            HAL_PIN_Set(PAD_PA11, GPIO_A11, PIN_PULLDOWN, 1);
261	#endif
262	        }
263	        else
264	        {
265	            battery_percentage = battery_calculator_get_percent(
266	                &battery_calc, 
267	                battery_level
268	            );
269	        }
270	
271	        rt_mb_send(g_battery_mb, battery_percentage);
272	        current_status = rt_pin_read(CHARGE_DETECT_PIN);
273	        rt_kprintf("battery_percentage: %d, current_status: %d: %d \n", battery_percentage, current_status);
274	#ifdef LOW_POWER_NO_SHUTDOWN  //针对立创没有电池的板子
275	
276	#else
277	        //当电量低于阈值并且当前没有处于充电中并的时候
278	        if (battery_percentage < LOW_BATTERY_THRESHOLD && low_battery_shutdown_triggered && !current_status) 
279	        {
280	            lv_obj_t *now_screen = lv_screen_active();
281	            rt_kprintf("now_screen address: %p, sleep_screen address: %p, standby_screen address: %p\n", 
282	               now_screen, sleep_screen, standby_screen);
283	            low_battery_shutdown_triggered = false;
284	            rt_kprintf("Low battery ,shutdown\n");
285	            //发送消息到UI线程显示低电量关机页面
286	            if (g_ui_task_mb != RT_NULL) 
287	            {
288	                if(now_screen == sleep_screen && now_screen != NULL)
289	                {
290	                    lowpower_shutdown_state = false;
291	                    gui_pm_fsm(GUI_PM_ACTION_WAKEUP); // 唤醒设备
292	
293	                }
294	                
295	                rt_thread_mdelay(100);
296	                rt_mb_send(g_ui_task_mb, UI_EVENT_LOW_BATTERY_SHUTDOWN);
297	            }
298	        }
299	#endif /* LOW_POWER_NO_SHUTDOWN */
300	        rt_thread_mdelay(5000);
301	    }
302	}
