396	void pan_reconnect()
397	{
398	    static int first_reconnect_attempts = 0;
399	    const int max_reconnect_attempts = 3;
400	
401	    LOG_I("Attempting to reconnect PAN, attempt %d",
402	          first_reconnect_attempts + 1);
403	    xiaozhi_ui_chat_status("重新连接 PAN...");
404	    xiaozhi_ui_chat_output("正在重连PAN...");
405	    xiaozhi_ui_standby_chat_output("正在重连PAN...");
406	    if (first_reconnect_attempts < max_reconnect_attempts)
407	    {
408	        // 使用与主流程中相同的定时器机制来连接PAN
409	        if (!g_bt_app_env.pan_connect_timer)
410	            g_bt_app_env.pan_connect_timer = rt_timer_create(
411	                "connect_pan", bt_app_connect_pan_timeout_handle,
412	                (void *)&g_bt_app_env,
413	                rt_tick_from_millisecond(PAN_TIMER_MS),
414	                RT_TIMER_FLAG_SOFT_TIMER);
415	        else
416	            rt_timer_stop(g_bt_app_env.pan_connect_timer);
417	        rt_timer_start(g_bt_app_env.pan_connect_timer);
418	        
419	        first_reconnect_attempts++;
420	    }
421	    else
422	    {
423	        LOG_W("Failed to keep_first_reconnect PAN after %d attempts",
424	              max_reconnect_attempts);
425	        xiaozhi_ui_chat_status("无法连接PAN");
426	        xiaozhi_ui_chat_output("请确保设备开启了共享网络,重新发起连接");
427	        xiaozhi_ui_update_emoji("thinking");
428	        xiaozhi_ui_standby_chat_output("请确保设备开启了共享网络,重新发起连接");
429	        // 重置尝试次数计数器，以便下次需要时重新开始
430	        first_reconnect_attempts = 0;
431	        
432	        // 停止定时器
433	        if (g_bt_app_env.pan_connect_timer) {
434	            rt_timer_stop(g_bt_app_env.pan_connect_timer);
435	        }
436	        
437	        return;
438	    }
439	}
