    if (g_pan_state.enabled) {
        LOG_W("PAN already initialized");
        return BT_STATUS_SUCCESS;
    }

    g_pan_state.enabled = true;
    g_pan_state.local_role = role;
    g_pan_state.max_connections = max_connections;
    g_pan_state.connected = false;
    memset(&g_pan_state.peer_addr, 0, sizeof(bt_address_t));

    return BT_STATUS_SUCCESS;
}

void bt_sal_pan_cleanup(void)
{
    LOG_I("PAN cleanup");

    if (!g_pan_state.enabled) {
        return;
    }

    if (g_pan_state.connected) {
        bt_sal_pan_disconnect(&g_pan_state.peer_addr);
    }

    g_pan_state.enabled = false;
